{
  "item_id": "PRISMA_2020_10a",
  "elements": [
    {
      "element_id": "prisma_2020_10a_e1",
      "status": "PRESENT",
      "chunk_id": "text_15",
      "quote": "The primary outcome of this systematic review and meta-analysis was estimating the pooled prevalence of MRPs among patients receiving cancer treatment in Ethiopia. Prevalence of MRPs was directly taken from the reports of the primary studies or calculated by dividing the number of patients experienced MRPs to the total number of study participants. While, variables reported as risk factor for the existence of MRPs and pooled prevalence of non-adherence were incorporated as a secondary outcome of interest.",
      "reason": "The manuscript explicitly lists and defines the primary outcome (pooled prevalence of MRPs) and secondary outcomes (risk factors for MRPs and pooled prevalence of non-adherence), and describes how prevalence was obtained/calculated."
    },
    {
      "element_id": "prisma_2020_10a_e2",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No information is provided specifying the time frame of measurement for each outcome domain (e.g., time points at which prevalence or other outcomes were measured)."
    },
    {
      "element_id": "prisma_2020_10a_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not state whether all results compatible with each outcome domain (for all measures, time points, analyses) were sought."
    },
    {
      "element_id": "prisma_2020_10a_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "There is no description of a process used to select among multiple compatible results within outcome domains (e.g., rules for choosing time points or measures) when not all results were sought."
    },
    {
      "element_id": "prisma_2020_10a_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No changes to outcome-domain inclusion, definitions, or importance are reported in the manuscript; therefore reporting changes with rationales does not apply based on the available evidence."
    },
    {
      "element_id": "prisma_2020_10a_e6",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No changes to the processes for selecting results within eligible outcome domains are reported; thus reporting such changes is not applicable in the provided evidence."
    },
    {
      "element_id": "prisma_2020_10a_e7",
      "status": "PARTIAL",
      "chunk_id": "text_15",
      "quote": "The primary outcome of this systematic review and meta-analysis was estimating the pooled prevalence of MRPs among patients receiving cancer treatment in Ethiopia. ... variables reported as risk factor for the existence of MRPs and pooled prevalence of non-adherence were incorporated as a secondary outcome of interest.",
      "reason": "The manuscript identifies the primary and secondary outcomes (indicating which outcomes were considered most important), but it does not provide a rationale explaining why these outcomes were prioritized for interpreting conclusions."
