{
  "item_id": "PRISMA_2020_11",
  "elements": [
    {
      "element_id": "prisma_2020_11_e1",
      "status": "PARTIAL",
      "chunk_id": "text_14",
      "quote": "The Newcastle-Ottawa quality assessment scale (NOS) adapted for observational studies was used to assess the quality of each original study [29].",
      "reason": "The risk-of-bias tool (Newcastle-Ottawa Scale) is named and stated as adapted for observational studies, but no specific version or detailed citation/version information is provided."
    },
    {
      "element_id": "prisma_2020_11_e2",
      "status": "PRESENT",
      "chunk_id": "text_14",
      "quote": "The quality assessment tool is divided into three sections. The first section concentrated on each original study's methodological quality, such as objectives, sample size, and sampling technique. This section was graded on a 5-star scale. The tool's second section evaluates study comparability and assigns a star rating out of two. The third section of the tool evaluates the outcome measures and data analysis and assigns a star rating out of three.",
      "reason": "The manuscript specifies the domains/components of the NOS (selection/methodological quality, comparability, outcome/data analysis) and how they are scored."
    },
    {
      "element_id": "prisma_2020_11_e3",
      "status": "PRESENT",
      "chunk_id": "text_14",
      "quote": "The NOS leveled a study as good if the score is 7-8, and very good for scores 9-10. The review and meta-analysis included studies with a score of 5 or higher.",
      "reason": "The report indicates an overall risk-of-bias judgement scheme (categorization into good/very good with score thresholds) and the inclusion cutoff used."
    },
    {
      "element_id": "prisma_2020_11_e4",
      "status": "PARTIAL",
      "chunk_id": "text_14",
      "quote": "The Newcastle-Ottawa quality assessment scale (NOS) adapted for observational studies was used to assess the quality of each original study [29].",
      "reason": "The manuscript states the NOS was 'adapted for observational studies' but does not describe what adaptations were made or how the tool was modified."
    },
    {
      "element_id": "prisma_2020_11_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No newly developed risk-of-bias tool is reported; the study used the established NOS (adapted)."
    },
    {
      "element_id": "prisma_2020_11_e6",
      "status": "PARTIAL",
      "chunk_id": "text_14",
      "quote": "The articles' quality was assessed by three authors (MBY, CT and DGD). The authors then compared the scores assigned to each study. Discrepancies in ratings were resolved through consensus.",
      "reason": "The number of reviewers (three) and the disagreement-resolution method (consensus) are reported, but it does not state whether assessments were done independently."
    },
    {
      "element_id": "prisma_2020_11_e7",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No information is provided about processes used to obtain or confirm risk-of-bias information from study investigators."
    },
    {
      "element_id": "prisma_2020_11_e8",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No automation tools for risk-of-bias assessment, nor their use/training/validation, are described."
    }
  ],
  "confidence": "80"
